53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	const COMPONENT_BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const CURSE_SURCHARGE_PERCENT = 50;
69	const HIGH_ENCHANTMENT_THRESHOLD = 5;
70	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
71	
72	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
73	const LOYALTY_DISCOUNT_PERCENT = 20;
74	const LOYALTY_MINIMUM_YEARS = 2;
75	
76	// Integer multiply before divide keeps fractional percentages exact
77	// (e.g. 10% of 25 is exactly 2.5 — no float noise from multiplying by 1.1).
78	const percentOf = (amount: number, percent: number): number =>
79	  (amount * percent) / 100;
80	
81	const isComponent = (item: QuoteItem): boolean =>
82	  COMPONENT_TYPES.includes(item.type);
83	
84	const basePremiumOf = (item: QuoteItem): number => BASE_PREMIUMS[item.type];
85	
86	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
87	  values.reduce((sum, value) => sum + amount(value), 0);
88	
89	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
90	
91	const isHighlyEnchanted = (item: QuoteItem): boolean =>
92	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
93	
94	// Item surcharge: a fixed percent of each qualifying item's base premium.
95	const itemSurcharge = (
96	  items: QuoteItem[],
97	  applies: (item: QuoteItem) => boolean,
98	  percent: number
99	): number =>
100	  sumBy(items.filter(applies), (item) => percentOf(basePremiumOf(item), percent));
101	
102	// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
103	const componentTypePremium = (items: QuoteItem[], type: string): number => {
104	  const count = items.filter((item) => item.type === type).length;
105	  return count === COMPONENT_BLOCK_SIZE
106	    ? COMPONENT_BLOCK_PREMIUM
107	    : count * BASE_PREMIUMS[type];
108	};
109	
110	const quotePremium = (
111	  items: QuoteItem[],
112	  customer: Customer,
113	  isFollowUpContract: boolean
114	): number => {
115	  const componentsPremium = sumBy(COMPONENT_TYPES, (type) =>
116	    componentTypePremium(items, type)
117	  );
118	  const mainItemsPremium = sumBy(
119	    items.filter((item) => !isComponent(item)),
120	    basePremiumOf
121	  );
122	  const policyBasePremium = componentsPremium + mainItemsPremium;
123	  const curseSurcharge = itemSurcharge(items, isCursed, CURSE_SURCHARGE_PERCENT);
124	  const enchantmentSurcharge = itemSurcharge(
125	    items,
126	    isHighlyEnchanted,
127	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT
128	  );
129	  // Policy-wide modifiers are all computed on the unmodified policy base.
130	  const firstInsuranceSurcharge = percentOf(
131	    policyBasePremium,
132	    FIRST_INSURANCE_SURCHARGE_PERCENT
133	  );
134	  const loyaltyDiscount =
135	    customer.yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS
136	      ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT)
137	      : 0;
138	  const followUpContractDiscount = isFollowUpContract
139	    ? percentOf(policyBasePremium, 15)
140	    : 0;
141	  return Math.ceil(
142	    policyBasePremium +
143	      curseSurcharge +
144	      enchantmentSurcharge +
145	      firstInsuranceSurcharge -
146	      loyaltyDiscount -
147	      followUpContractDiscount +
148	      PROCESSING_FEE
149	  );
150	};
