152	export const runScenario = (scenario: Scenario): ScenarioResult => {
153	  const results = scenario.steps.map((step, index) => {
154	    const quoteStep = step as QuoteStep;
155	    return {
156	      premium: quotePremium(quoteStep.items, scenario.customer, index > 0),
157	    };
158	  });
159	  return { results };
160	};
